type Envelope = { channelId: string; sequence: number; text: string };
type Send = (recipientId: string, envelope: Envelope) => Promise<void>;
let nextSequence = 0;

export async function publish(
  channelId: string,
  text: string,
  listMembers: (channelId: string) => Promise<string[]>,
  send: Send,
): Promise<void> {
  const sequence = ++nextSequence;
  const members = await listMembers(channelId);
  await Promise.all(
    members.map((recipientId) =>
      send(recipientId, { channelId, sequence, text }),
    ),
  );
}

type DeliveryState = "pending" | "delivered" | "cancelled";
interface MessageRepository {
  getState(id: string): Promise<DeliveryState | null>;
  setState(id: string, state: DeliveryState): Promise<void>;
}

export async function markDelivered(id: string, repo: MessageRepository): Promise<void> {
  const state = await repo.getState(id);
  if (state === null || state === "cancelled") return;
  await repo.setState(id, "delivered");
}

export async function cancelMessage(id: string, repo: MessageRepository): Promise<void> {
  const state = await repo.getState(id);
  if (state !== "pending") return;
  await repo.setState(id, "cancelled");
}

type Message = { channelId: string; body: string; sequence: number };
interface MessageStore {
  latestSequence(channelId: string): Promise<number>;
  insert(message: Message): Promise<void>;
}

export async function publishMessage(
  channelId: string,
  body: string,
  store: MessageStore,
): Promise<Message> {
  const latest = await store.latestSequence(channelId);
  const message = { channelId, body, sequence: latest + 1 };
  await store.insert(message);
  return message;
}
